 if($('#start-login')){$('#start-login').onclick=startLogin;$('#start-login').disabled=loginBusy;}if($('#cancel-login'))$('#cancel-login').onclick=cancelLogin;if($('#reconnect')){$('#reconnect').onclick=reconnect;$('#reconnect').disabled=reconnectBusy;}
