async function startLogin(){if(loginBusy)return;loginBusy=true;renderSetup();try{const login=await post('/api/auth/login',{});data.login=login;render();toast('Open the secure OpenAI sign-in link to continue.')}catch(e){toast(e.message)}finally{loginBusy=false;renderSetup()}}
async function cancelLogin(){try{await post('/api/auth/cancel',{});await refreshState()}catch(e){toast(e.message)}}
