 $('#settings-reconnect')?.addEventListener('click',reconnect);
 $('#add-project')?.addEventListener('submit',async e=>{e.preventDefault();const path=$('#project-path').value.trim(),label=$('#project-label').value.trim();if(!path)return;try{await post('/api/projects',{path,label});$('#project-path').value='';$('#project-label').value='';await refreshState();toast('Project added. You can select it in the request box.')}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-remove-project]').forEach(b=>b.onclick=async()=>{try{await post('/api/projects/remove',{projectId:b.dataset.removeProject});await refreshState();toast('Project removed from routing. Its files are unchanged.')}catch(e){toast(e.message)}});
