function workDuration(start){if(!start)return 'Start time unavailable';const seconds=Math.max(0,Math.floor((Date.now()-normalizeTime(start))/1000));return seconds>=3600?`${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m`:`${Math.floor(seconds/60)}m ${String(seconds%60).padStart(2,'0')}s`;}
function isLongWork(w){return ['running','starting','review'].includes(w.status)&&w.startedAt&&Date.now()-normalizeTime(w.startedAt)>=300000;}
function workCard(w){const started=!!w.startedAt,clock=started?w.startedAt:w.createdAt;return `<article class="work-card ${isLongWork(w)?'work-long':''}" data-work-card="${esc(w.key)}" data-work-status="${esc(w.status)}" data-work-start="${started?normalizeTime(w.startedAt):''}" style="--branch:${colors[w.department]||'#62d8fb'}"><div class="work-card-top"><div><span class="completion-context">${esc(w.department||'Choosing department')} / ${esc(w.projectLabel)}</span><h3>${esc(w.title)}</h3>${w.agentName?`<small>Agent: ${esc(w.agentName)}</small>`:''}</div><div class="work-time">${badge(w.status)}<strong data-elapsed="${clock?normalizeTime(clock):''}">${workDuration(clock)}</strong><small>${w.status==='uncertain'?'Outcome unconfirmed':started?w.status==='review'?'Turn open · needs your input':'Since execution started':['running','review'].includes(w.status)?'Execution start unconfirmed':'Since received · not running yet'}</small><span class="long-work-label" ${isLongWork(w)?'':'hidden'}>5+ minutes</span></div></div><div class="work-message"><span class="work-message-label">Exact request${w.prompt?'':' unavailable'}</span><div class="work-prompt" data-scroll-key="prompt:${esc(w.key)}">${w.prompt?esc(w.prompt):'The current turn’s message has not been exposed by Codex yet. An older message will not be substituted.'}</div></div><div class="work-latest"><strong>Latest activity</strong><span>${esc(w.latest)}</span>${w.latestAt?`<small>${time(w.latestAt)}</small>`:''}</div><div class="work-card-bottom"><small>${esc(prettyModel(w.model))} · ${esc(w.source)}</small><div><button class="primary" data-work-open="${esc(w.key)}">Inspect request</button>${w.threadId?`<button class="subtle" data-work-map="${esc(w.key)}">Show on map</button>`:''}</div></div><details class="work-receipt" data-details-key="${esc(w.key)}"><summary>Task and message receipts</summary><dl><dt>Task</dt><dd>${esc(w.threadId||'Awaiting dispatch')}</dd><dt>Turn</dt><dd>${esc(w.turnId||'Awaiting confirmed turn')}</dd>${w.jobId?`<dt>Request</dt><dd>${esc(w.jobId)}</dd>`:''}</dl></details></article>`;}
function workContent(preview=false){const all=unfinishedWork(),working=all.filter(w=>['running','starting','review'].includes(w.status));
 if(preview){if(!working.length)return '';return `<section class="work-preview" aria-label="Working now"><div class="section-heading"><div><h2>${working.length} ${working.length===1?'request is':'requests are'} still working</h2><p>Longest running first · each original message stays attached to its task</p></div><button class="subtle" data-view="working">View all active work</button></div>${working.slice(0,3).map(workCard).join('')}</section>`;}
 const filtered=all.filter(w=>workFilter==='all'||workFilter==='long'?workFilter==='all'||isLongWork(w):workFilter==='waiting'?['queued','routing','ready'].includes(w.status):workFilter==='uncertain'?w.status==='uncertain':['running','starting','review'].includes(w.status)).filter(w=>!workSearch||[w.title,w.prompt,w.department,w.projectLabel,w.agentName].join(' ').toLowerCase().includes(workSearch.toLowerCase()));
 return `<div class="section-heading work-heading"><h2>${filtered.length} ${filtered.length===1?'request':'requests'}</h2><div class="toolbar"><input class="search" id="work-search" aria-label="Search active messages" placeholder="Find a chat or exact message…" value="${esc(workSearch)}"><select id="work-filter" aria-label="Filter unfinished work">${[['working','Working now'],['long','5+ minutes'],['waiting','Waiting to start'],['uncertain','Outcome unconfirmed'],['all','All unfinished']].map(([v,n])=>`<option value="${v}" ${workFilter===v?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="work-list">${filtered.map(workCard).join('')||'<div class="empty"><h3>No requests match this view.</h3><p>Completed requests leave this list automatically. Check Completions for their results.</p></div>'}</div>`;
}
function bindWork(){document.querySelectorAll('[data-work-open],[data-work-map]').forEach(b=>b.onclick=()=>{const w=unfinishedWork().find(w=>w.key===(b.dataset.workOpen||b.dataset.workMap));if(!w)return;selected=w.jobId||findTask(w.threadId)?.id||w.threadId;inspectAgent=!w.jobId;
 if(b.dataset.workMap){view='overview';layout='graph';graphDepartment=w.department;graphProject=w.cwd||null;graphSearch='';graphFilter='all';mapCamera={x:0,y:0,z:1};inspectAgent=true;render();}else{renderInspector();$('#inspector').scrollTop=0;}
 });$('#work-filter')?.addEventListener('change',e=>{workFilter=e.target.value;renderContent();});$('#work-search')?.addEventListener('input',e=>{workSearch=e.target.value;renderContent();});document.querySelectorAll('[data-view="working"]').forEach(b=>b.onclick=()=>{view='working';workFilter='working';render();});}
function currentWorkDetails(t){const matches=unfinishedWork().filter(w=>t.local&&!inspectAgent?w.jobId===t.id:w.threadId===(t.threadId||t.id));return matches.length?`<section class="current-work"><h3>Current requests in this chat</h3>${matches.map(w=>`<div class="current-work-message">${badge(w.status)} <strong data-elapsed="${w.startedAt?normalizeTime(w.startedAt):''}">${workDuration(w.startedAt)}</strong><p data-scroll-key="current:${esc(w.key)}">${esc(w.prompt||'The exact current message is unavailable.')}</p><small>Turn: ${esc(w.turnId||'Awaiting dispatch')}</small></div>`).join('')}</section>`:'';}
let longWorkSignature='';
function updateWorkTimers(){if(view==='working'&&workFilter==='long'){const signature=unfinishedWork().filter(isLongWork).map(w=>w.key).join('|');if(signature!==longWorkSignature){longWorkSignature=signature;renderContent();}}document.querySelectorAll('[data-elapsed]').forEach(el=>el.textContent=workDuration(Number(el.dataset.elapsed)||null));document.querySelectorAll('[data-work-card]').forEach(el=>{const long=isLongWork({status:el.dataset.workStatus,startedAt:Number(el.dataset.workStart)||null});el.classList.toggle('work-long',!!long);el.querySelector('.long-work-label').hidden=!long;});}
function renderActivityConnection(){const desktop=data.desktop||{},agents=graphTasks(allTasks()),unknown=agents.filter(t=>t.activity?.state==='unknown'||['unknown','possibly_running'].includes(t.status)).length;const live=desktop.connected===true;$('#activity-connection').innerHTML=`<div><i class="connection-light ${data.connected?'connection-live':''}"></i><span>Execution engine<strong>${data.connected?'Connected':'Disconnected'}</strong></span></div><div><i class="connection-light ${live?'connection-live':''}"></i><span>Desktop agents<strong>${live?`Live / ${Number(desktop.observedThreads)||0} observed`:'Live observer disconnected'}</strong></span></div><p>${live?unknown?`${unknown} saved ${unknown===1?'task has':'tasks have'} no live status. These are not counted as running.`:'The active count shows confirmed running work.':`${esc(desktop.error||'Open Codex desktop to connect live agents.')} Desktop status is unavailable. The active count includes only work whose status can be verified.`}</p>`;}
function eventMillis(value){if(!value)return 0;return typeof value==='number'?(value<1e12?value*1000:value):Date.parse(value)||0}
function scheduleFlashExpiry(){if(flashExpiryTimer)clearTimeout(flashExpiryTimer);if(recordedFlashes.size)flashExpiryTimer=setTimeout(()=>{for(const [id,until] of recordedFlashes)if(until<=Date.now())recordedFlashes.delete(id);if(view==='overview')renderContent();if(selected&&!inspectorCollapsed)renderInspector();scheduleFlashExpiry()},Math.max(1,Math.min(...recordedFlashes.values())-Date.now()+10));}
function ingestActivity(next){const now=Date.now();for(const t of next.threads||[]){const stamp=t.lastEventAt||null,prior=recordedEventStamps.get(t.id),child=t.parentThreadId||t.activity?.parentThreadId;if(recordedHistorySeeded&&child&&prior&&stamp&&stamp!==prior&&eventMillis(stamp)>eventMillis(prior)&&t.activity?.state!=='running')recordedFlashes.set(t.id,now+2000);if(stamp&&(!prior||eventMillis(stamp)>=eventMillis(prior)))recordedEventStamps.set(t.id,stamp)}recordedHistorySeeded=true;for(const [id,until] of recordedFlashes)if(until<=now)recordedFlashes.delete(id);scheduleFlashExpiry();}
