 $('#sync-label').textContent=data.syncError?'Sync problem: '+data.syncError:`${data.threads.length} local Codex tasks · Last synced ${time(data.lastSync)} · Activity source and observation time appear in each task`;
 const modelKey=JSON.stringify(data.models.map(m=>[m.model,m.displayName]));if(modelKey!==lastModels){const value=$('#model').value;$('#model').innerHTML='<option value="">Auto · choose model</option>'+data.models.map(m=>`<option value="${esc(m.model)}">${esc(m.displayName)}</option>`).join('');$('#model').value=data.models.some(m=>m.model===value)?value:'';lastModels=modelKey;}
 const projectKey=JSON.stringify(data.projects.map(p=>[p.projectId,p.label]));if(projectKey!==lastProjects){const value=$('#project').value;$('#project').innerHTML='<option value="">Auto · choose project</option>'+data.projects.map(p=>`<option value="${esc(p.projectId)}">${esc(p.label)}</option>`).join('');$('#project').value=data.projects.some(p=>p.projectId===value)?value:'';lastProjects=projectKey;}
 $('#department-nav').innerHTML=data.departments.map(d=>`<button class="nav ${(graphDepartment===d&&view==='overview')?'active':''} ${graphTasks(allTasks()).some(t=>t.department===d&&isRunning(t))?'department-live':''}" data-department="${esc(d)}" title="${esc(d)}" aria-label="${esc(d)}"><span class="dept-dot" style="background:${colors[d]}"></span><span class="nav-text">${esc(d)}</span><b>${graphTasks(allTasks()).filter(t=>t.department===d).length}</b></button>`).join('');document.querySelectorAll('[data-department]').forEach(b=>b.onclick=()=>{graphDepartment=b.dataset.department;graphProject=null;department=null;view='overview';layout='graph';mapCamera={x:0,y:0,z:1};render()});
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 syncConversationChrome();
 const titles={chat:[activeChat()?.title||'Conversation','Messages and photos from this agent.','Conversation'],working:['Exactly what is still working.','Find the chat, original message, elapsed time and latest activity for every unfinished request.','Working now'],overview:['Your work. Connected.','A living map of your departments, projects, and Codex tasks.','Neural workspace'],requests:['Every request has a destination.','Saved first. Routed to the right work. Executed when capacity is available.','Request inbox'],attention:['The decisions waiting on you.','Resolve an approval, inspect a failure, or check an unconfirmed outcome.','Needs attention'],history:['Your Codex work, together.','Local tasks and their last recorded activity. Open a task to read its history.','Codex history'],notifications:['The work that finished.','Persistent results across departments, projects, and Codex tasks.','Completions'],settings:['Intelligence, with boundaries.','Choose capacity. See the models your Codex installation actually offers.','Models & capacity'],department:[department,`Tasks assigned to ${department?.toLowerCase()}. Departments are editable organization labels.`,department]};
 const title=titles[view];$('#page-title').textContent=title[0];$('#page-description').textContent=title[1];$('#breadcrumb-title').textContent=title[2];
 const agents=graphTasks(allTasks()),running=agents.filter(isRunning).length,queued=data.jobs.filter(j=>['queued','routing','ready'].includes(j.status)).length,attention=agents.filter(needsAttention).length,done=data.jobs.filter(j=>j.status==='completed').length;
 $('#metrics').innerHTML=[[running,'Active agents',data.desktop?.connected?'Confirmed running':'Desktop status unavailable'],[queued,'In the queue','Every request saved'],[attention,'Needs attention','Decisions & exceptions'],[done,'Completed here','Confirmed by Codex']].map(([n,l,h])=>`<div class="metric"><span class="metric-label">${l}</span><div class="metric-value"><strong>${n}</strong><span>${h}</span></div></div>`).join('');
 renderContent();if(selected&&!inspectorCollapsed)renderInspector();
