 const context=composerContext,fingerprint=JSON.stringify({messages,options});if(pendingSend?.fingerprint!==fingerprint)pendingSend={fingerprint,key:crypto.randomUUID()};const receipt=pendingSend;persistComposerDraft();sendBusy=true;$('#send').disabled=true;$('#receipt').textContent='Saving your request…';
