function workflowTrace(t){
 if(!t)return `<div class="workflow-empty"><span class="workflow-icon">⌁</span><div><strong>Every request has a path.</strong><span>Select a task to see its routing, execution, and result.</span></div><span class="workflow-hint">Click any node to inspect</span></div>`;
 if(!t.local)return `<div class="workflow-recorded"><span class="workflow-icon">◷</span><div><strong>${esc(compact(t.title,65))}</strong><span>${esc(t.department)} / ${esc(labels[t.status])} / ${esc(prettyModel(t.model))}</span></div><span class="provenance">${esc(activitySource(t))}</span></div>`;
 const stage=t.completedAt&&t.startedAt?4:t.startedAt||t.turnId?3:t.reason?2:1;
 return `<div class="trace-title"><span>${esc(compact(t.title,65))}</span>${badge(t.status)}</div><div class="workflow-trace">${['Received','Routed','Execution',t.status==='failed'?'Failed':t.status==='cancelled'?'Stopped':t.status==='uncertain'?'Unconfirmed':'Result'].map((name,i)=>`<div class="trace-step ${i<stage?'step-done':''} ${i===stage-1?'step-current':''}"><span>${i<stage-1?'✓':i+1}</span><div><strong>${name}</strong><small>${esc([time(t.createdAt),t.reason?t.department+' / '+prettyModel(t.model):'Choosing destination',t.waitReason|| (t.startedAt?time(t.startedAt):'Waiting for capacity'),t.completedAt?time(t.completedAt):'Awaiting a confirmed outcome'][i])}</small></div></div>`).join('')}</div>`;
}
