function fitUniverse(){
 if(!mapPositions.size){mapCamera={x:0,y:0,z:1};setCamera();return;}
 const points=[...mapPositions.values(),...mapExtent,{x:740,y:graphDepartment?105:455}],left=Math.min(...points.map(p=>p.x))-160,right=Math.max(...points.map(p=>p.x))+160,top=Math.min(...points.map(p=>p.y))-90,bottom=Math.max(...points.map(p=>p.y))+110;
 const z=Math.min(graphDepartment?2.2:1,1300/(right-left),760/(bottom-top));mapCamera={z,x:(740-(left+right)/2)*z,y:(455-(top+bottom)/2)*z};setCamera();
}
