let chatSelection=null,chatThreadId=null,chatReturnView='overview',chatFollowLive=true,composerContext='master',lastChatMarkup=null,photoViewerItems=[],photoViewerIndex=0;
const conversations=new Map(),composerDrafts=new Map();
function activeChat(){return graphTasks(allTasks()).find(t=>chatThreadId&&(t.threadId||t.id)===chatThreadId)||graphTasks(allTasks()).find(t=>t.id===chatSelection)||findTask(chatSelection)||data.threads.find(t=>t.id===chatThreadId);}
