function draftFor(key){if(!composerDrafts.has(key)){let saved;try{saved=JSON.parse(localStorage.getItem('ai-task-manager.draft:'+key)||'null')}catch{}let legacy='';try{if(key==='master')legacy=localStorage.getItem('rewster.command.draft')||''}catch{}const draft=saved||{text:legacy,images:[]};draft.images=(draft.images||[]).map(i=>i.id?i:{...i,status:'failed',error:'Upload interrupted. Remove and attach this photo again.'});composerDrafts.set(key,draft);}return composerDrafts.get(key);}
